"""#ifdef PYGRAM_UNSUPPORTED_EXIT
// pygram: errno -> the OSError subclass CPython's errnomap would have chosen.
//
// Deliberately a SUBSET of CPython's family. Each type costs an mp_obj_type_t
// (36 B of .rodata on i386: header plus four slots), a builtins-table entry and
// a qstr — about 68 B all in. The ones left out — BlockingIOError,
// ChildProcessError, the ConnectionError branch, InterruptedError,
// ProcessLookupError, TimeoutError — need a network, a process table or a
// signal, none of which exist in this guest (docs/PYGRAM-SUBSET.md §5). They
// stay UNDEFINED so `except TimeoutError:` keeps leaving through the honest
// exit-90 `builtin:` refusal, rather than being declared and never raised —
// which is the bug class the skill's §4b was written about.
const mp_obj_type_t *pygram_oserror_type(mp_int_t errno_) {
    switch (errno_) {
        case MP_ENOENT:
            return &mp_type_FileNotFoundError;
        case MP_EEXIST:
            return &mp_type_FileExistsError;
        case MP_EPERM:
        case MP_EACCES:
            return &mp_type_PermissionError;
        case MP_EISDIR:
            return &mp_type_IsADirectoryError;
        case MP_ENOTDIR:
            return &mp_type_NotADirectoryError;
        default:
            return &mp_type_OSError;
    }
}
#endif

mp_obj_t mp_obj_exception_make_new(const mp_obj_type_t *type, size_t n_args, size_t n_kw, const mp_obj_t *args) {
    mp_arg_check_num(n_args, n_kw, 0, MP_OBJ_FUN_ARGS_MAX, false);

    #ifdef PYGRAM_UNSUPPORTED_EXIT
    // pygram: CPython's OSError.__new__ returns an errno-mapped SUBCLASS, and
    // MicroPython has one flat OSError. That cost two different things: the
    // subclass NAMES were undefined, so the very common `except
    // FileNotFoundError:` left through the exit-90 `builtin:` refusal; and
    // `type(e).__name__` reported OSError where CPython reports the subclass,
    // at exit 0, which is the silent divergence §6 exists to stop.
    //
    // THE ARITY RULE IS CPYTHON'S, NOT A SIMPLIFICATION OF IT, and it is the
    // whole reason this hook is not just `n_args > 0`. Objects/exceptions.c
    // only parses an errno out of the arguments when 2 <= nargs <= 5, so
    // measured against CPython 3.11:
    //     OSError(2)                  -> OSError            (NOT mapped)
    //     OSError(2, "x")             -> FileNotFoundError
    //     OSError(2, "x", "f", 5, "w")-> FileNotFoundError
    //     OSError(2, ... 6 args ...)  -> OSError            (NOT mapped)
    //     OSError("2"), OSError(2.0, "x") -> OSError        (errno not an int)
    // Mapping a 1-argument OSError would MANUFACTURE a mismatch on a program
    // pygram runs correctly today, which is worse than the hole it closes.
    //
    // The failing open() does not come through here with two arguments — it
    // comes from mp_raise_OSError(errno) with one — so py/runtime.c has the
    // other half of this. Both are needed, and neither covers the other:
    // this one is the Python-level `raise OSError(...)` and
    // mp_raise_OSError_with_filename(); that one is every real OS failure.
    if (type == &mp_type_OSError && n_args >= 2 && n_args <= 5 && mp_obj_is_small_int(args[0])) {
        type = pygram_oserror_type(MP_OBJ_SMALL_INT_VALUE(args[0]));
    }
    #endif
""")

# ------------------------------------------ py/objexcept.c : the type table
